(function applyRealSquads() {
  const POS_ROLE = { GK: "goalkeeper", DF: "defender", MF: "midfielder", AT: "attacker" };
  function makeRows(rows) {
    const out = [];
    for (const row of rows || []) {
      const pos = row[0], name = row[1], ovr = row[2];
      const role = POS_ROLE[pos] || "midfielder";
      const p = makeRatedPlayer(name, ovr, role);
      p.role = role;
      out.push(p);
    }
    return out;
  }
  for (const team of Object.keys(REAL_SQUADS)) {
    if (!TEAM_ROSTERS[team]) continue;
    const sq = REAL_SQUADS[team];
    const roster = { defenders: [], midfielders: [], attackers: [], goalkeeper: null, bench: [], reserves: [] };
    for (const row of sq.xi || []) {
      const pos = row[0], name = row[1], ovr = row[2];
      const role = POS_ROLE[pos] || "midfielder";
      const p = makeRatedPlayer(name, ovr, role);
      p.role = role;
      if (pos === "GK" && !roster.goalkeeper) roster.goalkeeper = p;
      else if (pos === "DF") roster.defenders.push(p);
      else if (pos === "MF") roster.midfielders.push(p);
      else roster.attackers.push(p);
    }
    if (!roster.goalkeeper) roster.goalkeeper = makeRatedPlayer("GK", 65, "goalkeeper");
    roster.bench = makeRows(sq.bench);
    roster.reserves = makeRows(sq.reserves);
    if (typeof makeSquadDepth === "function") {
      const depth = makeSquadDepth(roster, team);
      const fill = (real, generated, quota) => {
        const counts = { goalkeeper: 0, defender: 0, midfielder: 0, attacker: 0 };
        const used = new Set();
        for (const p of real) { counts[p.role] = (counts[p.role] || 0) + 1; used.add(p.name); }
        for (const role of ["goalkeeper", "defender", "midfielder", "attacker"]) {
          while (real.length < 7 && (counts[role] || 0) < quota[role]) {
            const idx = generated.findIndex(p => p.role === role);
            if (idx < 0) break;
            const p = generated.splice(idx, 1)[0];
            real.push(p); used.add(p.name); counts[role]++;
          }
        }
        while (real.length < 7 && generated.length) {
          real.push(generated.shift());
        }
      };
      fill(roster.bench, depth.bench, { goalkeeper: 1, defender: 2, midfielder: 2, attacker: 2 });
      fill(roster.reserves, depth.reserves, { goalkeeper: 1, defender: 3, midfielder: 2, attacker: 1 });
    }
    TEAM_ROSTERS[team] = roster;
  }
})();
